fn chain_on(
    &mut self,
    text: String,
    sending: Sending,
    chain_stamp: Option<u128>,
    cx: &mut Context<Self>,
) {
    let Sending::Now(
        mode,
        attached,
        sliced,
        code_task,
        sent_from,
        post_build_update,
        named_after,
    ) = sending
    else {
        return self.start(text, sending, cx);
    };
    let lanes = Lanes::of(Some(mode));
    let earlier_waits = chain_stamp.is_some_and(|stamp| {
        self.queue
            .iter()
